ALTER TABLE evidence_attachment ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
CREATE TABLE sales_lead(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,customer_id TEXT NOT NULL,user_id TEXT NOT NULL,source TEXT NOT NULL,need TEXT NOT NULL,stage TEXT NOT NULL,expected_minor INTEGER NOT NULL DEFAULT 0,expected_invoice_date TEXT,next_action TEXT NOT NULL,next_due_at TEXT NOT NULL,lost_reason TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,stage_changed_at TEXT NOT NULL);
CREATE TABLE sales_order(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,customer_id TEXT NOT NULL,user_id TEXT NOT NULL,channel TEXT NOT NULL,client_order_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',version INTEGER NOT NULL DEFAULT 1,lines_json TEXT NOT NULL,net_minor INTEGER NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,submitted_by TEXT,approved_by TEXT,external_reference TEXT,UNIQUE(organization_id,user_id,client_order_id));
CREATE TABLE sales_order_revision(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,order_id TEXT NOT NULL,actor_id TEXT NOT NULL,occurred_at TEXT NOT NULL,before_json TEXT NOT NULL,after_json TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE order_policy(organization_id TEXT PRIMARY KEY,version INTEGER NOT NULL DEFAULT 1,name TEXT NOT NULL,require_stock_credit_review INTEGER NOT NULL DEFAULT 1,updated_by TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE forecast_contribution(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,customer_id TEXT NOT NULL,user_id TEXT NOT NULL,channel TEXT NOT NULL,source_kind TEXT NOT NULL,source_id TEXT,category TEXT NOT NULL,view_kind TEXT NOT NULL,expected_invoice_date TEXT NOT NULL,amount_minor INTEGER NOT NULL,reason TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE UNIQUE INDEX forecast_exclusive_customer ON forecast_contribution(organization_id,customer_id,channel,view_kind,substr(expected_invoice_date,1,7));
CREATE TABLE forecast_realization(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,contribution_id TEXT NOT NULL,view_kind TEXT NOT NULL,source_system TEXT NOT NULL,external_invoice_id TEXT NOT NULL,UNIQUE(organization_id,view_kind,source_system,external_invoice_id),UNIQUE(contribution_id,source_system,external_invoice_id));